String classify(Int n) {
  if n < 0 {
    return "neg"
  } else if n == 0 {
    return "zero"
  } else {
    return "pos"
  }
}

Int sumTo(Int n) {
  var sum = 0
  var i = 1
  while i <= n {
    sum = sum + i
    i = i + 1
  }
  return sum
}

run() {
  print(classify(-3))
  print(classify(0))
  print(classify(8))
  print("sum=" + sumTo(5))
}
